gameActivityClassAdditions.insert:
private final static String APEX_LAUNCHER_TAG = "ApexLauncher";
private String ApexDeviceSerialNumber = "";
private boolean bApexIsDeviceOwner = false;

public String AndroidThunkJava_GetApplicationVersionName(String packageName)
{
	try
	{
		PackageInfo packageInformation = getPackageManager().getPackageInfo(packageName, 0);
		return packageInformation.versionName != null ? packageInformation.versionName : "";
	}
	catch (Exception exception)
	{
		android.util.Log.w(APEX_LAUNCHER_TAG, "No version for " + packageName + ": " + exception);
	}

	return "";
}

public boolean AndroidThunkJava_PixoIsPackageInstalled(String packageName)
{
	return PixoUtilities.isPackageInstalled(getApplicationContext(), packageName);
}

public void AndroidThunkJava_LogAllPackages()
{
	PixoUtilities.logAllPackages(getApplicationContext());
}

// packageName may be "package", "package:action" or "package:action:component".
public boolean AndroidThunkJava_PixoLaunch(String packageName, String[] extraKeys, String[] extraValues, boolean bQuitAfterLaunch)
{
	String intentAction = "";
	String intentComponent = "";

	int separatorIndex = packageName.indexOf(":");
	if (separatorIndex >= 0)
	{
		intentAction = packageName.substring(separatorIndex + 1);
		packageName = packageName.substring(0, separatorIndex);

		separatorIndex = intentAction.indexOf(":");
		if (separatorIndex >= 0)
		{
			intentComponent = intentAction.substring(separatorIndex + 1);
			intentAction = intentAction.substring(0, separatorIndex);
		}
	}

	if (!PixoUtilities.isPackageInstalled(getApplicationContext(), packageName))
	{
		android.util.Log.e(APEX_LAUNCHER_TAG, packageName + " is not installed.");
		return false;
	}

	Intent launchIntent;
	if (intentAction.equals(""))
	{
		launchIntent = getPackageManager().getLaunchIntentForPackage(packageName);
		if (launchIntent == null)
		{
			return false;
		}
	}
	else
	{
		launchIntent = new Intent(intentAction);
		launchIntent.setPackage(packageName);
		launchIntent.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
	}

	for (int extraIndex = 0; extraIndex < extraKeys.length && extraIndex < extraValues.length; extraIndex++)
	{
		launchIntent.putExtra(extraKeys[extraIndex], extraValues[extraIndex]);
	}

	if (!intentComponent.equals(""))
	{
		launchIntent.setComponent(new ComponentName(packageName, intentComponent));
	}

	if (launchIntent.resolveActivity(getPackageManager()) == null)
	{
		return false;
	}

	startActivity(launchIntent);
	if (bQuitAfterLaunch)
	{
		AndroidThunkJava_ForceQuit();
	}

	return true;
}

public boolean AndroidThunkJava_PixoOpenURL(String url, boolean bQuitAfterLaunch)
{
	if (!url.contains("://") && !(url.indexOf(":") >= 1))
	{
		url = "http://" + url;
	}

	try
	{
		Intent browserIntent = new Intent(Intent.ACTION_VIEW, Uri.parse(url));
		browserIntent.addCategory(Intent.CATEGORY_BROWSABLE);
		browserIntent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
		if (browserIntent.resolveActivity(getPackageManager()) == null)
		{
			android.util.Log.e(APEX_LAUNCHER_TAG, "No application handles " + url);
			return false;
		}

		startActivity(browserIntent);
		if (bQuitAfterLaunch)
		{
			AndroidThunkJava_ForceQuit();
			finishAndRemoveTask();
		}

		return true;
	}
	catch (Exception exception)
	{
		android.util.Log.e(APEX_LAUNCHER_TAG, "Failed to open a URL: " + exception);
	}

	return false;
}

public void AndroidThunkJava_PixoQuit()
{
	AndroidThunkJava_ForceQuit();
	finishAndRemoveTask();
}

public String AndroidThunkJava_GetIntentData()
{
	Uri intentData = getIntent().getData();
	return intentData != null ? intentData.toString() : "";
}

public String AndroidThunkJava_GetApplicationExtra(String extraName)
{
	Bundle intentExtras = getIntent().getExtras();
	if (intentExtras == null)
	{
		return "";
	}

	Object extraValue = intentExtras.get(extraName);
	return extraValue != null ? extraValue.toString() : "";
}

public void AndroidThunkJava_PixoLog(String message)
{
	android.util.Log.i(APEX_LAUNCHER_TAG, message);
}

// Downloads the APK (or a zip holding it) from url, then installs it. Installing over an
// installed package updates it. Progress arrives through PixoEventNotifier.
public boolean AndroidThunkJava_InstallApplication(String packageName, String url)
{
	PixoDownloader packageDownloader = PixoDownloader.createDownloader(getApplicationContext(), url, packageName, ApexHeadsetType);
	packageDownloader.startDownloadPackage();
	return true;
}

public boolean AndroidThunkJava_UninstallApplication(String packageName)
{
	PixoInstaller packageInstaller = PixoInstaller.createInstaller(getApplicationContext(), packageName, null, ApexHeadsetType);
	packageInstaller.startUninstallPackage();
	return true;
}

public String AndroidThunkJava_GetAppFileLocation(String packageName)
{
	try
	{
		ApplicationInfo applicationInformation = getPackageManager().getApplicationInfo(packageName, 0);
		return applicationInformation.sourceDir;
	}
	catch (PackageManager.NameNotFoundException exception)
	{
		return "";
	}
}

// Shared storage: files in Download/, which outlive this app and other apps can read. A name
// without an extension gets ".txt", as in PixoCore; lookups try the name as given first.
private String ApexSharedFileName(String fileName)
{
	return fileName.contains(".") ? fileName : fileName + ".txt";
}

private Uri ApexFindSharedFileNamed(String displayName)
{
	ContentResolver resolver = getApplicationContext().getContentResolver();
	Uri collection = MediaStore.Downloads.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY);
	String selection = MediaStore.MediaColumns.DISPLAY_NAME + "=? AND " + MediaStore.MediaColumns.RELATIVE_PATH + "=?";
	String[] selectionArguments = { displayName, Environment.DIRECTORY_DOWNLOADS + "/" };

	try (Cursor cursor = resolver.query(collection, new String[] { MediaStore.MediaColumns._ID }, selection, selectionArguments, null))
	{
		if (cursor != null && cursor.moveToFirst())
		{
			long fileId = cursor.getLong(cursor.getColumnIndexOrThrow(MediaStore.MediaColumns._ID));
			return ContentUris.withAppendedId(collection, fileId);
		}
	}
	catch (Exception exception)
	{
		android.util.Log.e(APEX_LAUNCHER_TAG, "Failed to look up " + displayName + ": " + exception);
	}

	return null;
}

private Uri ApexFindSharedFile(String fileName)
{
	if (Build.VERSION.SDK_INT < 29)
	{
		return null;
	}

	Uri fileUri = ApexFindSharedFileNamed(fileName);
	if (fileUri == null && !fileName.endsWith(".txt"))
	{
		fileUri = ApexFindSharedFileNamed(fileName + ".txt");
	}

	return fileUri;
}

public boolean AndroidThunkJava_FileExists(String fileName)
{
	return ApexFindSharedFile(fileName) != null;
}

public String AndroidThunkJava_WriteFileToSharedStorage(String fileName, String content)
{
	if (Build.VERSION.SDK_INT < 29)
	{
		return "";
	}

	ContentResolver resolver = getApplicationContext().getContentResolver();
	Uri existingUri = ApexFindSharedFile(fileName);
	if (existingUri != null)
	{
		try
		{
			resolver.delete(existingUri, null, null);
		}
		catch (Exception exception)
		{
			android.util.Log.e(APEX_LAUNCHER_TAG, "Failed to replace " + fileName + ": " + exception);
		}
	}

	ContentValues fileValues = new ContentValues();
	fileValues.put(MediaStore.MediaColumns.DISPLAY_NAME, ApexSharedFileName(fileName));
	fileValues.put(MediaStore.MediaColumns.MIME_TYPE, "text/plain");
	fileValues.put(MediaStore.MediaColumns.RELATIVE_PATH, Environment.DIRECTORY_DOWNLOADS);

	Uri newUri = resolver.insert(MediaStore.Downloads.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY), fileValues);
	if (newUri == null)
	{
		return "";
	}

	try (OutputStream outputStream = resolver.openOutputStream(newUri, "w"))
	{
		if (outputStream != null)
		{
			outputStream.write(content.getBytes(StandardCharsets.UTF_8));
			return newUri.toString();
		}
	}
	catch (IOException exception)
	{
		android.util.Log.e(APEX_LAUNCHER_TAG, "Failed to write " + fileName + ": " + exception);
	}

	return "";
}

public String AndroidThunkJava_ReadFileFromSharedStorage(String fileName)
{
	Uri fileUri = ApexFindSharedFile(fileName);
	if (fileUri == null)
	{
		return "";
	}

	ContentResolver resolver = getApplicationContext().getContentResolver();
	try (InputStream inputStream = resolver.openInputStream(fileUri);
		BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream, StandardCharsets.UTF_8)))
	{
		StringBuilder contentBuilder = new StringBuilder();
		String line;
		while ((line = reader.readLine()) != null)
		{
			if (contentBuilder.length() > 0)
			{
				contentBuilder.append("\n");
			}

			contentBuilder.append(line);
		}

		return contentBuilder.toString();
	}
	catch (Exception exception)
	{
		android.util.Log.e(APEX_LAUNCHER_TAG, "Failed to read " + fileName + ": " + exception);
	}

	return "";
}

public boolean AndroidThunkJava_DeleteFileFromSharedStorage(String fileName)
{
	Uri fileUri = ApexFindSharedFile(fileName);
	if (fileUri == null)
	{
		return false;
	}

	try
	{
		return getApplicationContext().getContentResolver().delete(fileUri, null, null) > 0;
	}
	catch (SecurityException exception)
	{
		android.util.Log.e(APEX_LAUNCHER_TAG, "Failed to delete " + fileName + ": " + exception);
	}

	return false;
}

// The serial ManageXR reports, else the one the system properties give, else "".
public String AndroidThunkJava_GetDeviceSerialNumber()
{
	if (ApexDeviceSerialNumber != null && !ApexDeviceSerialNumber.isEmpty())
	{
		return ApexDeviceSerialNumber;
	}

	String systemSerialNumber = PixoUtilities.getSerialNumber();
	return systemSerialNumber != null ? systemSerialNumber : "";
}

public String AndroidThunkJava_GetMacAddress()
{
	return PixoUtilities.getMacAddress();
}

public boolean AndroidThunkJava_IsDeviceOwner()
{
	return bApexIsDeviceOwner;
}

