protected final ConfigPackManager.ConfigPackListener ApexConfigPackListener = new ConfigPackManager.ConfigPackListener()
{
	@Override
	public void onSuccess()
	{
		android.util.Log.i(APEX_LAUNCHER_TAG, "Config pack imported.");
	}

	@Override
	public void onFail(int errorCode, String errorMessage)
	{
		android.util.Log.e(APEX_LAUNCHER_TAG, "Config pack import failed: " + errorCode + " " + errorMessage);
	}
};

// Imports PIXOConfigImage.zip with its .key from the app's external files directory.
public void ApexImportConfigurationPackages()
{
	try
	{
		File externalDirectory = getApplicationContext().getExternalFilesDir(null);
		File keyFile = new File(externalDirectory, "PIXOConfigImage.key");
		File imageFile = new File(externalDirectory, "PIXOConfigImage.zip");
		if (!keyFile.exists() || !imageFile.exists())
		{
			android.util.Log.w(APEX_LAUNCHER_TAG, "No config pack in " + externalDirectory);
			return;
		}

		CustomizedService.importConfigPackThirdParty(imageFile.getAbsolutePath(), keyFile.getAbsolutePath(), ApexConfigPackListener);
	}
	catch (Exception exception)
	{
		android.util.Log.e(APEX_LAUNCHER_TAG, "Config pack import failed: " + exception);
	}
}

gameActivityOnCreateAdditions.insert:
DeviceOwnerReceiver.setTargetApplicationName("com.PixoVR.PixoHub");

if (PermissionHelper.checkPermission("android.permission.ACCESS_WIFI_STATE") == false)
{
	PermissionHelper.acquirePermissions(new String[] { "android.permission.ACCESS_WIFI_STATE" });
}

MXRAdminAppMessenger apexAdminAppMessenger = new MXRAdminAppMessenger(this);
apexAdminAppMessenger.onSerialUpdated((serial) -> {
	ApexDeviceSerialNumber = serial;
});
bApexIsDeviceOwner = apexAdminAppMessenger.isManaged();

true.insert:
DevicePolicyManager apexPolicyManager = (DevicePolicyManager)getSystemService(Context.DEVICE_POLICY_SERVICE);
if (apexPolicyManager != null)
{
	ComponentName apexAdmin = new ComponentName(getApplicationContext(), com.Pixo.PixoPlatform.DeviceOwnerReceiver.class);
	if (apexPolicyManager.isDeviceOwnerApp(getPackageName()) && apexPolicyManager.isAdminActive(apexAdmin))
	{
		apexPolicyManager.setPermissionGrantState(apexAdmin, getPackageName(), android.Manifest.permission.INSTALL_PACKAGES, DevicePolicyManager.PERMISSION_GRANT_STATE_GRANTED);
	}
}

try
{
	CustomizedService.init(getApplicationContext(), new CustomizedService.InitListener()
	{
		@Override
		public void onConnected()
		{
			String configPackCode = CustomizedService.getConfigPackRecognitionCode();
			if (configPackCode == null || configPackCode.isEmpty())
			{
				ApexImportConfigurationPackages();
			}
		}

		@Override
		public void onDisconnected()
		{
		}
	});
}
catch (Exception exception)
{
	android.util.Log.e(APEX_LAUNCHER_TAG, "Failed to start the HTC customized service: " + exception);
}

ToBServiceHelper.getInstance().bindTobService(getApplicationContext(), new ToBServiceHelper.BindCallBack()
{
	@Override
	public void bindCallBack(Boolean status)
	{
		android.util.Log.i(APEX_LAUNCHER_TAG, "Pico ToB service bound: " + status);
	}
});
